1	<!DOCTYPE html>
2	<html lang="de">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Monster Walk</title>
7	  <style>
8	    * {
9	      margin: 0;
10	      padding: 0;
11	      box-sizing: border-box;
12	    }
13	
14	    :root {
15	      /* Sprite sheet monsters/green-fuzz-classic.png: 23 frames of 276 × 300 px,
16	         transparent. Source: one gait cycle from the 24 fps video, cut out and
17	         aligned to a shared ground line and body axis. The vertical bob lives in
18	         the frames themselves – no artificial bounce needed in CSS.
19	
20	         Every number below belongs to that one sheet. Another monster means
21	         another frame count, cell size and cycle time – the roster with those
22	         figures is the table in MONSTER-DEV.md §5. */
23	      --frame-w: 184px;                        /* display width of a single frame */
24	      --frame-h: 200px;                        /* 300/276 × 184 → keeps the aspect ratio */
25	      --sheet-w: calc(var(--frame-w) * 23);    /* 4232px – must match steps(23) */
26	      --ground: 90px;                          /* height of the ground strip */
27	      --cycle: 0.96s;                          /* 23 frames at 24 fps = original tempo */
28	      /* Stride: the distance covered by one full gait cycle. This is what sets the
29	         walking speed – too large and the feet slide across the ground. Smaller =
30	         slower and more mincing, larger = faster and more slippery. */
31	      --stride: 130px;
32	      --crossing: 16s;                         /* fallback; the script below derives it from --stride */
33	    }
34	
35	    body {
36	      min-height: 100vh;
37	      background: linear-gradient(#dff0f7, #eef8fb 70%);
38	      overflow: hidden;
39	      position: relative;
40	    }
41	
42	    .ground {
43	      position: absolute;
44	      inset: auto 0 0 0;
45	      height: var(--ground);
46	      background: #cfe6c9;
47	      border-top: 3px solid #a9cfa0;
48	    }
49	
50	    /* The wrapper handles the travel across the screen … */
51	    .walker {
52	      position: absolute;
53	      left: 0;
54	      bottom: calc(var(--ground) - 3px);      /* feet rest on the edge of the ground */
55	      width: var(--frame-w);
56	      height: var(--frame-h);
57	      animation: move-across var(--crossing) linear 1 forwards;
58	    }
59	
60	    /* The shadow sits under the leading foot, not under the tail.
61	       The monster walks right → left, so it belongs on the right-hand side. */
62	    .shadow {
63	      position: absolute;
64	      right: 8%;
65	      width: 42%;
66	      bottom: 0;
67	      height: 11px;
68	      background: rgba(60, 80, 60, 0.22);
69	      border-radius: 50%;
70	      filter: blur(3px);
71	    }
72	
73	    /* … the sprite only flips through the frames. */
74	    .monster {
75	      position: absolute;
76	      inset: 0;
77	      background-image: url("monsters/green-fuzz-classic.png");
78	      background-repeat: no-repeat;
79	      background-size: var(--sheet-w) var(--frame-h);
80	      /*transform: scaleX(-1);*/               /* mirror the sprite: monster faces left */
81	      animation: walk-cycle var(--cycle) steps(23) infinite;
82	    }
83	
84	    /* Flips through all 23 frames */
85	    @keyframes walk-cycle {
86	      from { background-position: 0 0; }
87	      to   { background-position: calc(-1 * var(--sheet-w)) 0; }
88	    }
89	
90	    /* Walks once from the right edge all the way out of frame */
91	    @keyframes move-across {
92	      from { transform: translateX(100vw); }
93	      to   { transform: translateX(calc(-1 * var(--frame-w))); }
94	    }
95	
96	    @media (prefers-reduced-motion: reduce) {
97	      .walker { animation: none; transform: translateX(40vw); }
98	      .monster { animation: none; }
99	    }
100	  </style>
101	  <script>
102	    /* The distance to walk depends on the window width, the gait tempo does not.
103	       With a fixed duration the monster would move faster on wide monitors and its
104	       feet would slide. So the duration is derived from the stride instead: a whole
105	       number of gait cycles, each one --cycle long and --stride wide. */
106	    (() => {
107	      const root = document.documentElement;
108	      const px = (name) => parseFloat(getComputedStyle(root).getPropertyValue(name));
109	
110	      const distance = window.innerWidth + px('--frame-w');
111	      const cycles = Math.max(1, Math.round(distance / px('--stride')));
112	      root.style.setProperty('--crossing', (cycles * px('--cycle')).toFixed(2) + 's');
113	    })();
114	  </script>
115	</head>
116	<body>
117	  <div class="ground"></div>
118	  <div class="walker">
119	    <div class="shadow"></div>
120	    <div class="monster"></div>
121	  </div>
122	</body>
123	</html>
