:root {
  /* Sprite sheet assets/monster.png: 23 frames of 276×300 px, one gait cycle,
     cut from 24 fps footage. The vertical bob is baked into the frames. */
  --monster-frame-w: 184px;
  --monster-frame-h: 200px;
  --monster-frames: 23;
  --monster-sheet-w: calc(var(--monster-frame-w) * var(--monster-frames));
  --monster-cycle: 0.958s;
  --monster-stride: 130px; /* ground distance per gait cycle — the speed knob */
}

.monster-walker {
  position: fixed;
  left: 0;
  bottom: 0;
  width: var(--monster-frame-w);
  height: var(--monster-frame-h);
  z-index: 9999;
  pointer-events: none;
  transform: translateX(calc(-1 * var(--monster-frame-w)));
}

.monster-walker.walking {
  animation: monster-cross var(--monster-crossing) linear 1 forwards;
}

@keyframes monster-cross {
  from { transform: translateX(calc(-1 * var(--monster-frame-w))); }
  to   { transform: translateX(100vw); }
}

.monster-face {
  position: absolute;
  inset: 0;
  transform: scaleX(-1); /* artwork faces left; mirror it to face the direction of travel */
}

.monster-shadow {
  position: absolute;
  right: 8%;
  bottom: 0;
  width: 42%;
  height: 11px;
  background: rgba(30, 40, 30, 0.25);
  border-radius: 50%;
  filter: blur(3px);
}

.monster-sprite {
  position: absolute;
  inset: 0;
  background-image: url("assets/monster.png");
  background-repeat: no-repeat;
  background-size: var(--monster-sheet-w) var(--monster-frame-h);
}

.monster-walker.walking .monster-sprite {
  animation: monster-gait var(--monster-cycle) steps(var(--monster-frames)) infinite;
}

@keyframes monster-gait {
  from { background-position: 0 0; }
  to   { background-position: calc(-1 * var(--monster-sheet-w)) 0; }
}

@media (prefers-reduced-motion: reduce) {
  .monster-walker.walking,
  .monster-walker.walking .monster-sprite {
    animation: none;
  }
}

