// retrigger while walking should be ignored
await page.keyboard.down('Alt');
await page.keyboard.press('A');
await page.keyboard.up('Alt');
const countMid = await page.$$eval('.monster-walker', (els) => els.length);
console.log('walker count while walking (retrigger should be ignored):', countMid);

// wait for it to finish and clean itself up
await page.waitForSelector('.monster-walker', { state: 'detached', timeout: 20000 });
console.log('walker removed itself after crossing finished');

// reduced motion check
const page2 = await browser.newPage({ viewport: { width: 1280, height: 800 }, reducedMotion: 'reduce' });
await page2.goto(`http://localhost:${port}/`);
await page2.keyboard.down('Alt');
await page2.keyboard.press('A');
await page2.keyboard.up('Alt');
await page2.waitForSelector('.monster-walker', { timeout: 2000 });
const reducedTransform = await page2.$eval('.monster-walker', (el) => getComputedStyle(el).transform);
console.log('reduced-motion transform (should be static, non-animating):', reducedTransform);
await page2.waitForTimeout(500);
const reducedTransform2 = await page2.$eval('.monster-walker', (el) => getComputedStyle(el).transform);
console.log('reduced-motion transform after 500ms (should match, i.e. not moving):', reducedTransform2);
await page2.waitForSelector('.monster-walker', { state: 'detached', timeout: 5000 });
console.log('reduced-motion walker cleaned up too');

console.log('console/page errors:', errors);

await browser.close();
server.close();

