57	footer {
58	  padding: 1.5rem 2rem;
59	  text-align: center;
60	  color: #7a7266;
61	  font-size: 0.9rem;
62	}
63	
64	:root {
65	  /* Sprite sheet assets/monster.png: 23 frames of 276×300 px, one gait cycle,
66	     cut from 24 fps footage. The vertical bob is baked into the frames. */
67	  --monster-frame-w: 184px;
68	  --monster-frame-h: 200px;
69	  --monster-frames: 23;
70	  --monster-sheet-w: calc(var(--monster-frame-w) * var(--monster-frames));
71	  --monster-cycle: 0.958s;
72	  --monster-stride: 130px; /* ground distance per gait cycle — the speed knob */
73	}
74	
75	.monster-walker {
76	  position: fixed;
77	  left: 0;
78	  bottom: 0;
79	  width: var(--monster-frame-w);
80	  height: var(--monster-frame-h);
81	  z-index: 9999;
82	  pointer-events: none;
83	  transform: translateX(calc(-1 * var(--monster-frame-w)));
84	}
85	
86	.monster-walker.walking {
87	  animation: monster-cross var(--monster-crossing) linear 1 forwards;
88	}
89	
90	@keyframes monster-cross {
91	  from { transform: translateX(calc(-1 * var(--monster-frame-w))); }
92	  to   { transform: translateX(100vw); }
93	}
94	
95	.monster-face {
96	  position: absolute;
97	  inset: 0;
98	  transform: scaleX(-1); /* artwork faces left; mirror it to face the direction of travel */
99	}
100	
101	.monster-shadow {
102	  position: absolute;
103	  right: 8%;
104	  bottom: 0;
105	  width: 42%;
106	  height: 11px;
107	  background: rgba(30, 40, 30, 0.25);
108	  border-radius: 50%;
109	  filter: blur(3px);
110	}
111	
112	.monster-sprite {
113	  position: absolute;
114	  inset: 0;
115	  background-image: url("assets/monster.png");
116	  background-repeat: no-repeat;
117	  background-size: var(--monster-sheet-w) var(--monster-frame-h);
118	}
