    walker.addEventListener('animationend', () => {
      walker.remove();
      walking = false;
    });
    requestAnimationFrame(() => walker.classList.add('walking'));
  }

  document.addEventListener('keydown', (e) => {
    if (e.altKey && e.code === 'KeyA') {
      e.preventDefault();
      walkMonster();
    }
  });
})();

