import { chromium } from 'playwright';
import { createServer } from 'http';
import { readFile } from 'fs/promises';
import { extname, join } from 'path';

const ROOT = '<home>/source/repos/priv/monster-dev-testruns/2026-08-01-index-sonnet';
const MIME = { '.html': 'text/html', '.css': 'text/css', '.js': 'text/javascript', '.svg': 'image/svg+xml', '.png': 'image/png' };

const server = createServer(async (req, res) => {
  let path = req.url === '/' ? '/index.html' : req.url;
  try {
    const data = await readFile(join(ROOT, path));
    res.writeHead(200, { 'Content-Type': MIME[extname(path)] || 'application/octet-stream' });
    res.end(data);
  } catch {
    res.writeHead(404);
    res.end('not found');
  }
});

await new Promise((resolve) => server.listen(0, resolve));
const port = server.address().port;
console.log('serving on', port);

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });

await page.goto(`http://localhost:${port}/`);

const existsBefore = await page.$('.monster-walker');
console.log('before keypress, walker exists:', !!existsBefore);

await page.evaluate(() => {
  window.__log = [];
  const t0 = performance.now();
  const obs = new MutationObserver((muts) => {
    for (const m of muts) {
      window.__log.push({ t: (performance.now() - t0).toFixed(1), type: m.type, attr: m.attributeName, target: m.target.className });
    }
  });
  obs.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'] });
  window.__t0 = t0;
});

await page.keyboard.down('Alt');
await page.keyboard.press('A');
await page.keyboard.up('Alt');

await page.waitForSelector('.monster-walker', { timeout: 2000 });
console.log('walker appeared after Alt+A');

const diag0 = await page.$eval('.monster-walker', (el) => ({
  crossingVar: el.style.getPropertyValue('--monster-crossing'),
  classes: el.className,
  anims: el.getAnimations().map(a => ({ playState: a.playState, currentTime: a.currentTime, duration: a.effect?.getTiming?.().duration })),
}));
console.log('diag right after walking class added:', JSON.stringify(diag0));

await page.waitForTimeout(300);
const midTransform = await page.$eval('.monster-walker', (el) => getComputedStyle(el).transform);
console.log('mid-walk transform:', midTransform);
const diag1 = await page.$eval('.monster-walker', (el) => el.getAnimations().map(a => ({ playState: a.playState, currentTime: a.currentTime })));
console.log('diag after 300ms:', JSON.stringify(diag1));

await page.waitForTimeout(3000);
const laterTransform = await page.$eval('.monster-walker', (el) => getComputedStyle(el).transform);
console.log('transform after +3000ms more:', laterTransform);

const mutationLog = await page.evaluate(() => window.__log);
console.log('mutation log:', JSON.stringify(mutationLog));
await page.screenshot({ path: '<home>/AppData/Local/Temp/claude/<home>-source-repos-priv-monster-dev-testruns-2026-08-01-index-sonnet/d6c89f41-1c9d-4f87-a047-aaab74758293/scratchpad/mid-walk.png' });

// retrigger while walking should be ignored
await page.keyboard.down('Alt');
await page.keyboard.press('A');
await page.keyboard.up('Alt');
const countMid = await page.$$eval('.monster-walker', (els) => els.length);
console.log('walker count while walking (retrigger should be ignored):', countMid);

// wait for it to finish and clean itself up
await page.waitForSelector('.monster-walker', { state: 'detached', timeout: 20000 });
